// ssd1306_hal.h — Lab 14 Measurement, STM32 F446RE (HAL version)
//
// Drop-in replacement for ssd1306.h — identical public API, but the
// implementation uses HAL_I2C_Master_Transmit instead of bare-metal I2C.
//
// REQUIREMENTS:
//   - CubeIDE project with I2C1 configured at 400 kHz (Fast Mode)
//   - PB8 = I2C1_SCL,  PB9 = I2C1_SDA  (selected in IOC Pinout view)
//   - SSD1306 I2C address: 0x3C  (SA0 pin tied to GND on module)
//   - The HAL handle  hi2c1  is generated by CubeIDE in main.c/gen.c
//
// USAGE:
//   #include "ssd1306_hal.h"
//   SSD1306_Init();            // call after MX_I2C1_Init()
//   SSD1306_DrawString(0, 0, "Hello");
//   SSD1306_Update();

#ifndef SSD1306_HAL_H
#define SSD1306_HAL_H

#include <stdint.h>

// =========================================================================
// SSD1306_Init — run the display init sequence and clear the screen.
// Call AFTER I2C1_Init (MX_I2C1_Init in CubeIDE).
// =========================================================================
void SSD1306_Init(void);

// =========================================================================
// SSD1306_Clear — zero the RAM framebuffer.
// Does NOT update the display — call SSD1306_Update() afterward.
// =========================================================================
void SSD1306_Clear(void);

// =========================================================================
// SSD1306_DrawString — render a null-terminated ASCII string at col, page.
// col:  0–127  (pixel column)
// page: 0–7    (text row, each page = 8 pixel rows)
// Does NOT update the display.
// =========================================================================
void SSD1306_DrawString(uint8_t col, uint8_t page, const char *s);

// =========================================================================
// SSD1306_DrawHLine — draw a 1-pixel horizontal rule at page 'page'.
// Does NOT update the display.
// =========================================================================
void SSD1306_DrawHLine(uint8_t page);

// =========================================================================
// SSD1306_DrawBar — progress bar at 'page', filled to 'percent' (0–100).
// Does NOT update the display.
// =========================================================================
void SSD1306_DrawBar(uint8_t page, uint8_t percent);

// =========================================================================
// SSD1306_Update — flush the 1024-byte framebuffer to the SSD1306 GDDRAM.
// Sends all 1025 bytes (1 control + 1024 data) in one I2C transaction.
// Duration: ~23 ms at 400 kHz.
// =========================================================================
void SSD1306_Update(void);

#endif // SSD1306_HAL_H
